// Giriş formlarının saf mantığı: yazarken e-posta süzme ve alan doğrulama iletileri. E-posta denetimi ABACUS'tandır.
// Kural: giris-alanlari-standardi.md (yazarken boşluk kırp ve küçük harfe çevir; kaydederken doğrulama motorunu çağır).
import { text, validate } from "@snn/abacus-core";

/** Giriş formlarının Türkçe ekran metinleri; `login-split` ve `login-immersive` aynı iletileri kullanır. */
export const LOGIN_TEXT = {
  email: "E-posta",
  password: "Parola",
  remember: "Beni hatırla",
  forgot: "Parolamı unuttum",
  submit: "Giriş yap",
  submitting: "Giriş yapılıyor",
  done: "Giriş yapıldı",
  or: "ya da",
  noAccount: "Hesabın yok mu?",
  signUp: "Kayıt ol",
  emailProblem: "Geçerli bir e-posta yazın.",
  passwordProblem: "Parola boş olamaz.",
  failed: "E-posta ya da parola hatalı.",
} as const;

/** E-posta yazarken süzme: boşluklar atılır, ASCII küçük harfe çevrilir (Türkçe büyük I küçük ı olmaz). */
export function cleanLoginEmail(raw: string): string {
  return text.toAsciiLower(raw.replace(/\s+/g, ""));
}

/** Boş ya da biçimsiz e-postada ileti, geçerliyse null. Yazarken değil; alandan çıkınca ve gönderimde çağrılır. */
export function loginEmailProblem(email: string): string | null {
  return email && validate.email(email) ? null : LOGIN_TEXT.emailProblem;
}

/** Parola yalnız boş olup olmadığına bakılır; gücünü ve doğruluğunu sunucu denetler. */
export function loginPasswordProblem(password: string): string | null {
  return password ? null : LOGIN_TEXT.passwordProblem;
}

/** Gönderimde ilk hatalı alanın adı (odak oraya gider); hepsi geçerliyse null. */
export function firstInvalidField(email: string, password: string): "email" | "password" | null {
  if (loginEmailProblem(email)) return "email";
  if (loginPasswordProblem(password)) return "password";
  return null;
}

/** Hata kutusunun metni: proje kendi metnini verdiyse o, yoksa (ya da yalnız boşluksa) "E-posta ya da parola hatalı.". */
export function loginAlertText(error?: string): string {
  return error?.trim() ? error : LOGIN_TEXT.failed;
}

/* İki giriş bloğunun ortak form gövdesi. Renk, boşluk ve hareket yalnız foundation değişkenlerinden. */
.form { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-4); min-width: 0; }
.alertSlot { overflow: hidden; }
.alert { margin: 0; padding: var(--space-3) var(--space-4); border: 1px solid color-mix(in oklch, var(--danger) 35%, transparent); border-radius: var(--radius-control); background: color-mix(in oklch, var(--danger) 9%, var(--surface)); color: var(--danger); font-size: var(--text-sm); }
.passwordWrap { display: grid; gap: var(--space-1); }
.fieldError { margin: 0; color: var(--danger); font-size: var(--text-sm); }
.options { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-3); flex-wrap: wrap; }
.options[data-remember] { justify-content: space-between; }
.link { min-height: 1.5rem; padding: 0; border: 0; background: none; color: var(--accent-strong); font: inherit; font-size: var(--text-sm); text-decoration: underline; cursor: pointer; }
.link:hover { color: var(--foreground); }
.link:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; border-radius: 2px; }
.link:disabled { color: var(--text-muted); cursor: default; }
.submit, .provider { width: 100%; }
.providers { display: grid; gap: var(--space-3); }
.divider { display: flex; align-items: center; gap: var(--space-3); color: var(--text-muted); font-size: var(--text-sm); }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

"use client";

import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from "react";
import { AnimatePresence, animate, motion } from "motion/react";
import { Button } from "../button/button";
import { Checkbox } from "../checkbox/checkbox";
import { Input } from "../input/input";
import { PasswordField } from "../password-field/password-field";
import { motionTokens } from "../lib/motion-tokens";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { LOGIN_TEXT, cleanLoginEmail, firstInvalidField, loginAlertText, loginEmailProblem, loginPasswordProblem } from "./login-form-format";
import styles from "./login-form.module.css";

export interface LoginValues { email: string; password: string; remember?: boolean | undefined }
export interface LoginProvider { id: string; label: string; icon?: ReactNode | undefined }
export const DEFAULT_PROVIDERS: LoginProvider[] = [{ id: "google", label: "Google ile devam et" }];

type Status = "idle" | "sending" | "error" | "done";

export interface LoginFormProps {
  /** Giriş denemesini yapar; sözü reddederse form üstünde hata kutusu açılır. */
  onSubmit: (values: LoginValues) => Promise<unknown>;
  onForgot?: ((email: string) => void) | undefined;
  onProvider?: ((id: string) => void) | undefined;
  providers?: LoginProvider[] | undefined;
  /** "Beni hatırla" kutusunu gösterir; `onSubmit` değerine `remember` olarak girer. */
  showRemember?: boolean | undefined;
  /** Açılış kademesinin başlangıç gecikmesi (sn). */
  introDelay?: number | undefined;
  /** Formu adlandıran başlığın kimliği (`aria-labelledby`). */
  labelledBy?: string | undefined;
  /** Alanların başlangıç değerleri; yalnız ilk çizimde okunur. E-posta yazarken olduğu gibi süzülür. */
  defaultValues?: Partial<LoginValues> | undefined;
  /** Hata kutusunun metni. Dolu verilince kutu bu metinle açılır (örneğin "Hesabınız kilitlendi."); reddedilen girişte de varsayılan metnin yerine bu yazılır.
   * Kullanıcı alanlara yazınca kutu kapanır; yeni bir metin verilince yeniden açılır. */
  error?: string | undefined;
  /** Form öğesine yazılır; uçtan uca testlerde formu bulmak için. */
  "data-testid"?: string | undefined;
}

/** İki giriş bloğunun ortak gövdesi: alanlar, gönderim durumları, hata kutusu ve sağlayıcı düğmeleri. Başlık ve kayıt satırı kabın işidir. */
export function LoginForm({ onSubmit, onForgot, onProvider, providers = DEFAULT_PROVIDERS, showRemember = false, introDelay = 0, labelledBy, defaultValues, error, "data-testid": testId }: LoginFormProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const submitRef = useRef<HTMLButtonElement>(null);
  const shakeRef = useRef<HTMLDivElement>(null);
  const [email, setEmail] = useState(() => cleanLoginEmail(defaultValues?.email ?? ""));
  const [password, setPassword] = useState(defaultValues?.password ?? "");
  const [remember, setRemember] = useState(defaultValues?.remember ?? false);
  const [touched, setTouched] = useState({ email: false, password: false });
  const [status, setStatus] = useState<Status>(error ? "error" : "idle");
  const mounted = useRef(false);

  const emailError = touched.email ? loginEmailProblem(email) : null;
  const passwordError = touched.password ? loginPasswordProblem(password) : null;
  const sending = status === "sending";

  // Hata gelince alanlar yeniden açılır; odak ve sallanma bundan sonra parola alanına verilir.
  // İlk çizimde gelen hata yalnız gösterilir: sayfa açılır açılmaz odak çalınmaz, form sallanmaz.
  useEffect(() => {
    const first = !mounted.current;
    mounted.current = true;
    if (status !== "error" || first) return;
    passwordRef.current?.focus();
    if (!reduced && shakeRef.current) animate(shakeRef.current, { x: [0, -6, 6, -4, 4, 0] }, { duration: .35 });
  }, [status, reduced]);

  // Dışarıdan yeni bir hata metni gelince kutu açılır.
  useEffect(() => { if (error) setStatus(current => current === "sending" ? current : "error"); }, [error]);

  const edit = () => { if (status === "error" || status === "done") setStatus("idle"); };

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (sending) return;
    setTouched({ email: true, password: true });
    const invalid = firstInvalidField(email, password);
    if (invalid) { (invalid === "email" ? emailRef : passwordRef).current?.focus(); return; }
    setStatus("sending");
    submitRef.current?.focus();
    try {
      await onSubmit(showRemember ? { email, password, remember } : { email, password });
      setStatus("done");
    } catch { setStatus("error"); }
  };

  const rise = (order: number) => reduced ? {} : { initial: { opacity: 0, y: 12 }, animate: { opacity: 1, y: 0 }, transition: { duration: motionTokens.duration.considered, ease: [...motionTokens.ease.enter] as [number, number, number, number], delay: introDelay + order * motionTokens.stagger.item * 2 } };
  const label = status === "sending" ? LOGIN_TEXT.submitting : status === "done" ? LOGIN_TEXT.done : LOGIN_TEXT.submit;

  return <form className={styles.form} data-testid={testId} onSubmit={submit} noValidate aria-labelledby={labelledBy} aria-busy={sending || undefined}>
    <AnimatePresence initial={false}>
      {status === "error" && <motion.div key="alert" className={styles.alertSlot} role="alert" initial={reduced ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { height: 0, opacity: 0 }} transition={reduced ? { duration: 0 } : motionTokens.spring.smooth}>
        <p className={styles.alert}>{loginAlertText(error)}</p>
      </motion.div>}
    </AnimatePresence>
    <motion.div {...rise(0)}>
      <Input ref={emailRef} label={LOGIN_TEXT.email} name="email" type="email" inputMode="email" autoComplete="email" placeholder="ad@ornek.com.tr" value={email} error={emailError ?? undefined} disabled={sending}
        onChange={event => { setEmail(cleanLoginEmail(event.target.value)); edit(); }} onBlur={() => { if (email) setTouched(current => ({ ...current, email: true })); }} />
    </motion.div>
    <motion.div {...rise(1)}>
      <div ref={shakeRef} className={styles.passwordWrap}>
        <PasswordField ref={passwordRef} label={LOGIN_TEXT.password} name="password" autoComplete="current-password" value={password} disabled={sending}
          aria-invalid={passwordError ? true : undefined} aria-describedby={passwordError ? `${uid}-password-error` : undefined}
          onChange={event => { setPassword(event.target.value); edit(); }} onBlur={() => { if (password) setTouched(current => ({ ...current, password: true })); }} />
        <AnimatePresence initial={false}>
          {passwordError && <motion.p key="error" id={`${uid}-password-error`} role="alert" className={styles.fieldError} initial={reduced ? false : { opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, transition: { duration: reduced ? 0 : motionTokens.duration.instant } }} transition={reduced ? { duration: 0 } : { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}>{passwordError}</motion.p>}
        </AnimatePresence>
      </div>
    </motion.div>
    <motion.div className={styles.options} data-remember={showRemember || undefined} {...rise(2)}>
      {showRemember && <Checkbox label={LOGIN_TEXT.remember} checked={remember} onCheckedChange={next => setRemember(next === true)} disabled={sending} />}
      <button type="button" className={styles.link} disabled={sending} onClick={() => onForgot?.(email)}>{LOGIN_TEXT.forgot}</button>
    </motion.div>
    <motion.div {...rise(3)}>
      <Button ref={submitRef} type="submit" variant="primary" size="lg" className={styles.submit} loading={sending} disabled={status === "done"}>{label}</Button>
    </motion.div>
    {providers.length > 0 && <motion.div className={styles.providers} {...rise(4)}>
      <div className={styles.divider} role="separator"><span>{LOGIN_TEXT.or}</span></div>
      {providers.map(provider => <Button key={provider.id} type="button" variant="secondary" size="lg" className={styles.provider} disabled={sending} onClick={() => onProvider?.(provider.id)}>{provider.icon}{provider.label}</Button>)}
    </motion.div>}
    <div className={styles.srOnly} role="status" aria-live="polite" aria-atomic="true">{sending ? LOGIN_TEXT.submitting : status === "done" ? LOGIN_TEXT.done : ""}</div>
  </form>;
}

/* İki bölmeli giriş: kap genişliğine göre düzen (container query). Renk ve ölçüler foundation değişkenlerinden. */
.root { container-type: inline-size; position: relative; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); background: var(--background); color: var(--foreground); overflow: hidden; }
.formPane { grid-row: 2; display: grid; place-items: center; min-width: 0; padding: var(--space-8) var(--space-4); }
.formBox { display: grid; gap: var(--space-5); width: min(100%, 27.5rem); min-width: 0; }
.brand { display: flex; align-items: center; gap: var(--space-2); font-family: var(--font-display); font-size: var(--text-lg); font-weight: 600; }
.mark { display: inline-grid; place-items: center; width: 2rem; height: 2rem; border-radius: var(--radius-control); background: var(--accent); color: var(--accent-foreground); }
.heading { display: grid; gap: var(--space-1); }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-2xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.subtitle { margin: 0; color: var(--text-secondary); }
.signup { margin: 0; text-align: center; color: var(--text-secondary); font-size: var(--text-sm); }
.link { padding: 0; border: 0; background: none; color: var(--accent-strong); font: inherit; text-decoration: underline; cursor: pointer; min-height: 1.5rem; }
.link:hover { color: var(--foreground); }
.link:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; border-radius: 2px; }

/* Görsel bölme: dar kapta formun üstünde ince şerit. Fotoğraf üstü yazı ve degrade sabit açık/koyu tondur (tema değişse de okunur). */
.mediaPane { grid-row: 1; position: relative; isolation: isolate; overflow: hidden; height: 7.5rem; display: flex; flex-direction: column; justify-content: flex-end; padding: var(--space-6); color: oklch(100% 0 0); }
.surface { position: absolute; inset: 0; z-index: -1; background:
  radial-gradient(60% 70% at 20% 15%, color-mix(in oklch, var(--accent) 55%, transparent), transparent 70%),
  radial-gradient(55% 60% at 85% 85%, color-mix(in oklch, var(--accent-strong) 35%, transparent), transparent 70%),
  var(--neutral-10); }
.surface::after { content: ""; position: absolute; inset: 0; background: linear-gradient(to top, oklch(0% 0 0 / .62), oklch(0% 0 0 / 0) 65%); }
.photo { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.badge { position: absolute; top: var(--space-4); left: var(--space-4); padding: var(--space-1) var(--space-3); border: 1px solid oklch(100% 0 0 / .3); border-radius: var(--radius-pill); background: oklch(0% 0 0 / .28); backdrop-filter: blur(8px); font-size: var(--text-xs); }
.quote { display: none; margin: 0; max-width: 32rem; gap: var(--space-4); }
.quoteText { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); line-height: 1.35; text-wrap: balance; }
.person { display: flex; align-items: center; gap: var(--space-3); }
.personText { display: grid; font-size: var(--text-sm); }
.personText b { font-weight: 600; }
.personText span { color: oklch(100% 0 0 / .78); }

@container (min-width: 768px) {
  .root { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: minmax(0, 1fr); }
  .formPane { grid-row: 1; grid-column: 1; padding: var(--space-12) var(--space-8); }
  .mediaPane { grid-row: 1; grid-column: 2; height: auto; padding: var(--space-10); }
  .root[data-media-side="left"] .formPane { grid-column: 2; }
  .root[data-media-side="left"] .mediaPane { grid-column: 1; }
  .quote { display: grid; }
  .badge { top: var(--space-6); left: var(--space-6); }
}

"use client";

import { useId, useState } from "react";
import { motion } from "motion/react";
import { Avatar } from "../avatar/avatar";
import { motionTokens } from "../lib/motion-tokens";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { LoginForm, type LoginProvider, type LoginValues } from "./login-form";
import { LOGIN_TEXT } from "./login-form-format";
import styles from "./login-split.module.css";

export type { LoginProvider, LoginValues };

export interface LoginSplitProps {
  /** Giriş denemesini yapar; reddederse form üstünde "E-posta ya da parola hatalı." çıkar. Gerçek kimlik doğrulamayı uygulama bağlar. */
  onSubmit: (values: LoginValues) => Promise<unknown>;
  /** "Parolamı unuttum"a basınca girilmiş e-postayla çağrılır; sayfa değişmez. */
  onForgot?: ((email: string) => void) | undefined;
  /** Sağlayıcı düğmesine basınca sağlayıcının kimliğiyle çağrılır. */
  onProvider?: ((id: string) => void) | undefined;
  /** "Kayıt ol" bağlantısına basınca çağrılır. */
  onSignUp?: (() => void) | undefined;
  /** Form üstündeki marka işareti ve adı. `mark` küçük bir simge ya da logo olabilir. */
  brand?: { name: string; mark?: React.ReactNode | undefined } | undefined;
  title?: string | undefined;
  subtitle?: string | undefined;
  /** Görsel bölmenin fotoğrafı; verilmezse ya da yüklenemezse vurgu renginden türetilmiş yüzey çizilir. */
  media?: { src: string; alt?: string | undefined } | undefined;
  /** Görsel bölmedeki alıntı ve sahibi. Dar kapta gizlenir. */
  quote?: { text: string; name: string; role?: string | undefined; avatar?: string | undefined } | undefined;
  /** Görsel bölmenin üstündeki küçük rozet. */
  badge?: string | undefined;
  mediaSide?: "left" | "right" | undefined;
  providers?: LoginProvider[] | undefined;
  showRemember?: boolean | undefined;
  /** Bölümün en az yüksekliği; varsayılan ekran yüksekliğidir. */
  minHeight?: string | undefined;
  /** Form alanlarının başlangıç değerleri (`LoginForm` ile aynı). */
  defaultValues?: Partial<LoginValues> | undefined;
  /** Hata kutusunun metni (`LoginForm` ile aynı). */
  error?: string | undefined;
  /** Formun kendisine yazılır; uçtan uca testlerde formu bulmak için. */
  "data-testid"?: string | undefined;
}

/** Ürün girişi için iki bölmeli ekran kullanın: bir yanda sade form, öbür yanda güven veren fotoğraf ve alıntı. Dar kapta (768 px altı) fotoğraf ince bir şeride iner. Ortada tek kart için `login-centered`, tam ekran fotoğraf üstünde kart için `login-immersive`. Bileşen yalnız görünüm ve olay çağrılarıdır; kimlik doğrulamayı uygulama yapar. */
export function LoginSplit({ onSubmit, onForgot, onProvider, onSignUp, brand, title = "Tekrar hoş geldiniz", subtitle = "Hesabınıza giriş yapın", media, quote, badge, mediaSide = "right", providers, showRemember = true, minHeight = "100svh", defaultValues, error, "data-testid": testId }: LoginSplitProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const [failedSrc, setFailedSrc] = useState<string>();
  const showPhoto = media?.src && failedSrc !== media.src;

  const fade = (delay: number) => reduced ? {} : { initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: { duration: motionTokens.duration.considered, ease: [...motionTokens.ease.enter] as [number, number, number, number], delay } };

  return <section className={styles.root} style={{ minHeight }} data-media-side={mediaSide} data-reduced={reduced || undefined} aria-labelledby={`${uid}-title`}>
    <div className={styles.formPane}>
      <div className={styles.formBox}>
        {brand && <motion.div className={styles.brand} {...fade(0)}>{brand.mark && <span className={styles.mark} aria-hidden="true">{brand.mark}</span>}<span>{brand.name}</span></motion.div>}
        <motion.div className={styles.heading} {...fade(.04)}>
          <h1 id={`${uid}-title`} className={styles.title}>{title}</h1>
          <p className={styles.subtitle}>{subtitle}</p>
        </motion.div>
        <LoginForm onSubmit={onSubmit} defaultValues={defaultValues} error={error} data-testid={testId} onForgot={onForgot} onProvider={onProvider} providers={providers} showRemember={showRemember} introDelay={.1} labelledBy={`${uid}-title`} />
        <motion.p className={styles.signup} {...fade(.5)}>{LOGIN_TEXT.noAccount} <button type="button" className={styles.link} onClick={() => onSignUp?.()}>{LOGIN_TEXT.signUp}</button></motion.p>
      </div>
    </div>
    <div className={styles.mediaPane}>
      <motion.div className={styles.surface} initial={reduced ? false : { scale: 1.04 }} animate={{ scale: 1 }} transition={reduced ? { duration: 0 } : { duration: motionTokens.duration.considered * 2, ease: [...motionTokens.ease.enter] as [number, number, number, number] }} aria-hidden="true">
        {showPhoto && <img className={styles.photo} src={media.src} alt="" onError={() => setFailedSrc(media.src)} />}
      </motion.div>
      {badge && <span className={styles.badge}>{badge}</span>}
      {quote && <motion.figure className={styles.quote} {...fade(.35)}>
        <blockquote className={styles.quoteText}>{"“"}{quote.text}{"”"}</blockquote>
        <figcaption className={styles.person}>
          <Avatar name={quote.name} src={quote.avatar} size="md" />
          <span className={styles.personText}><b>{quote.name}</b>{quote.role && <span>{quote.role}</span>}</span>
        </figcaption>
      </motion.figure>}
    </div>
  </section>;
}

export default LoginSplit;
